from __future__ import annotations

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.tracer import tracer


class RecentlyMethods(BaseClient):
    @tracer.start_as_current_span("recently.wim_recently_setAttentionAttribute")
    def wim_recently_setAttentionAttribute(self, sn: str, value: int | str = 1) -> dict:
        """
        Метод для отметки чата как непрочитанного
        """
        return self.post(
            "wim/recently/setAttentionAttribute",
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            data={
                "sn": sn,
                "value": value,
                "aimsid": self.aimsid,
                "f": "json",
                "r": self.getReqId(),
            },
        )
